#!/usr/bin/env python3
"""Generate Crystaleye's tarot pages, shop, and browser card data."""
import json
from html import escape as e
from site_images import image_tag, brand_mark
from pathlib import Path
from site_components import merchandise, ROOT, CATALOG, mobile_toolbar
from decimal import Decimal

CARDS=json.loads((ROOT/'data/tarot-cards.json').read_text())['cards']
LEARNING=json.loads((ROOT/'data/tarot-learning.json').read_text())
OUT=ROOT/'tarot'

def img(card, cls='', eager=False):
    return f'<img class="{cls}" src="../assets/images/tarot/{card}.webp" alt="{e(next((c["name"]+" tarot card in cyberpunk artwork" for c in CARDS if c["id"]==card),"Crystal Eye tarot card back"))}" width="480" height="720" loading="{"eager" if eager else "lazy"}" decoding="async">'

def shell(title,desc,body,shop=False):
    css='../tarot/tarot.css' if shop else 'tarot.css'
    module='' if shop else '<script type="module" src="tarot.js"></script>'
    tarot_home='../tarot/index.html' if shop else 'index.html'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111219"><meta name="description" content="{e(desc)}"><title>{e(title)} | Crystaleye</title><link rel="icon" href="../assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="{css}"><link rel="stylesheet" href="../assets/merchandise.css"><link rel="stylesheet" href="../assets/cyberpunk.css"><link rel="stylesheet" href="../assets/mobile-toolbar.css"><script src="../assets/site.js" defer></script>{module}</head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header wrap"><a class="brand" href="../index.html" aria-label="Crystaleye home">{brand_mark('../')}<span>crystaleye<span class="brand-dot">.</span></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav"><span>Menu</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 6h14M3 14h14"/></svg></button><nav id="site-nav" aria-label="Main navigation"><a href="{tarot_home}">Tarot</a><a href="{tarot_home}#learn">Learn the cards</a><a href="../astrology/index.html">Astrology</a></nav><a class="header-cta" href="../shop/index.html">Books, decks &amp; a little wonder →</a></header><main id="main">{body}{'' if shop else merchandise('../')}</main><footer class="site-footer wrap tarot-footer"><a class="brand" href="../index.html">crystaleye<span class="brand-dot">.</span></a><nav aria-label="Footer"><a href="{tarot_home}#daily-draw">Your daily draw</a><a href="{tarot_home}#learn">Explore the cards</a><a href="../shop/index.html">Books &amp; decks</a><a href="../numerology/index.html">Numerology</a><a href="../index.html">Crystaleye home →</a></nav><p>Tarot offers symbolic prompts for reflection and entertainment, not a guaranteed forecast. An easy or demanding theme does not determine what will happen. Your choices and circumstances matter.</p></footer>{mobile_toolbar('../',None if shop else 'Tarot')}</body></html>'''

def slot(name, index):
    return f'''<div class="card-slot" data-slot="{index}"><div class="draw-card"><div class="flip-inner"><div class="card-face card-back">{img('card-back',eager=True)}<span class="card-back-label">{name}</span></div><div class="card-face card-front"><img data-front alt="Card not yet drawn" width="480" height="720"></div></div></div><p class="draw-card-name" data-card-name>Waiting for your draw</p></div>'''

def card_tile(c):
    number=f'{c["number"]:02d}' if c['arcana']=='major' else c['rank']
    return f'''<article class="study-card">{img(c['id'])}<div><p class="eyebrow">{number}</p><h3>{e(c['name'])}</h3><p class="card-keywords">{e(c['keywords'])}</p><details><summary>Read this card</summary><p>{e(c['energy'])}</p><p class="study-question">{e(c['lesson'])}</p></details></div></article>'''

def hub():
    links=''.join(f'<a href="{s["slug"]}.html"><span>{s["element"]}</span><h3>{s["name"]} →</h3><p>{e(s["domains"])}</p></a>' for s in LEARNING['suits'])
    body=f'''<section class="wrap tarot-hero"><div><p class="eyebrow"><span class="tiny-star" aria-hidden="true">✧</span> The Crystaleye tarot room</p><h1>A new day.<br>A fresh <em>perspective.</em></h1><p class="section-copy">A little easier, a little demanding, or somewhere in between. Pull a card, meet the day’s theme, and choose how you want to respond.</p><div class="hero-actions"><a class="button button-gold" href="#daily-draw">Take a breath. Draw a card →</a><a class="text-link" href="#what-is-tarot">New to tarot? Start here →</a></div><p class="fine-print">78 cards. A little wonder. Always your own story.</p></div><div class="hero-card-fan" aria-label="The Fool, Star, and Sun from the Crystal Eye deck">{img('the-fool','fan-left',True)}{img('the-star','fan-center',True)}{img('the-sun','fan-right',True)}</div></section>
<section class="wrap section-space" id="daily-draw"><div class="tarot-topline"><p class="eyebrow">01 / Your free daily card</p><p class="fine-print" data-today>One draw per local date, in this browser tab</p></div><h2>Meet today’s <em>rhythm.</em></h2><p class="section-copy">An easier-day theme, a mixed current, or something that asks a little more of you. Your card pairs that theme with a practical way to approach the day.</p><div class="daily-panel" id="free-widget"><div class="single-altar">{slot('Your daily card',0)}<span class="altar-line" aria-hidden="true"></span></div><div class="daily-copy"><p class="eyebrow">One card. One small check-in.</p><div id="free-result" aria-live="polite" aria-atomic="true"><h3>Make a little room<br>for the unexpected.</h3><p>Pause, take a breath, then reveal your card. The whole 78-card deck is in the shuffle; readings use upright meanings.</p></div><button class="button button-gold" id="free-draw" type="button" disabled>Enable JavaScript to draw</button><p class="draw-status fine-print" id="free-status" role="status"></p><p class="fine-print">Saved in this tab’s session for the current local date. Refreshing keeps your draw; closing the session clears it. Nothing is sent to a server.</p><noscript><p class="notice">Enable JavaScript to shuffle and save your daily card. You can still explore all the learning pages and deck artwork below.</p></noscript></div></div><details class="session-journal"><summary>Your session journal</summary><p class="fine-print">Daily cards and sample spreads from this tab, kept for up to 30 dates. This is a local journal, not an account or a subscription.</p><ol id="draw-history"><li>No draws yet. Your first card is a good place to begin.</li></ol></details><p id="storage-notice" class="fine-print" role="status"></p></section>
<section class="tarot-subscription section-space" id="subscription"><div class="wrap subscribe-layout"><div><p class="eyebrow">02 / A deeper daily ritual</p><h2>Yesterday.<br>Today.<br><em>A little tomorrow.</em></h2><p class="section-copy">Three cards, one daily pause. A reflection on what you are carrying, a focus for the present, and a hopeful perspective on what you might welcome next.</p><p class="tarot-price">$5.99 <span>CAD / month</span></p><p class="coming-soon">Coming soon · subscriptions are not open yet</p><a class="button button-gold" href="#three-card-preview">Try the animated preview →</a><p class="fine-print">The tarot subscription is separate from the astrology subscription. Payments and account access will be connected later.</p></div><ol class="spread-positions"><li><span>01 / Yesterday</span><h3>What can you learn?</h3><p>Reflect on the previous day: a response, a pattern, or a small lesson you can carry forward. This is an invitation to notice, not a judgment about what you should already know.</p></li><li><span>02 / Today</span><h3>Where does your energy belong?</h3><p>Give the present a useful focus: an action to take, a boundary to hold, or a way of meeting what is actually in front of you.</p></li><li><span>03 / Tomorrow</span><h3>What might you welcome?</h3><p>A gratitude prompt for a possibility to cultivate or receive. This card offers a hopeful way to look ahead, without promising a particular event.</p></li></ol></div><div class="wrap spread-preview" id="three-card-preview"><div class="tarot-topline"><p class="eyebrow">A taste of the three-card ritual</p><span class="preview-badge">Public preview · no subscription is active</span></div><p class="section-copy">Try one sample spread for today, saved in this tab. It shows how the planned subscription will feel; it does not enroll you or unlock a paid account.</p><button class="button button-outline" id="spread-draw" type="button" disabled>Enable JavaScript for the preview</button><p class="draw-status fine-print" id="spread-status" role="status"></p><div class="spread-grid" id="spread-widget">{''.join(f'<article class="spread-position"><p class="eyebrow">{name}</p>{slot(name,i)}<div class="position-reading" data-reading="{i}"><h3>{heading}</h3><p>{copy}</p></div></article>' for i,(name,heading,copy) in enumerate([('Yesterday','A lesson to keep','What could you learn from a moment, choice, or feeling you are carrying?'),('Today','A focus to choose','Where could your attention make a useful difference right now?'),('Tomorrow','A possibility to welcome','What could you appreciate, cultivate, or be open to receiving?')]))}</div></div></section>
<section class="wrap section-space" id="what-is-tarot"><div class="tarot-topline"><p class="eyebrow">03 / Come curious</p><span class="section-aside">A deck. A question. A different angle.</span></div><h2>What is <em>tarot?</em></h2><div class="tarot-intro-grid"><p>Tarot is a deck of illustrated cards used for games, storytelling, and reflective reading. A typical modern deck has 78 cards: 22 Major Arcana and 56 Minor Arcana. Its documented roots lie in fifteenth-century European card games; later traditions developed the symbolic reading practices familiar today.</p><p>The Major Arcana explores broad themes and transitions. The Minor Arcana brings those questions into daily life through Swords, Cups, Pentacles, and Wands. A reading combines a question, a card’s imagery and meanings, and its position in a spread. It can open a useful conversation with yourself without making your future fixed.</p></div><div class="tarot-faq"><details open><summary>How can I get a reading?</summary><p>Begin with the free daily draw above: one upright card with an easy, mixed, or more demanding-day theme and a practical response. Try the three-card preview for yesterday, today, and tomorrow. The planned daily three-card subscription is $5.99 CAD/month; enrollment is coming later. These are on-screen self-reflection readings, not bookings with a live reader.</p><a href="#daily-draw">Draw today’s card →</a></details><details><summary>How can I get my own deck?</summary><p>The Crystal Eye Tarot Deck is listed at $39.99 CAD, with a book-and-deck bundle at $49.99 CAD. Browse the artwork and product details in our shop. Ordering is not open yet; format, fulfillment, and final checkout details will be published before purchases begin.</p><a href="../shop/index.html#deck">Explore the deck →</a></details><details><summary>How can I learn to read?</summary><p>Start by noticing the image before looking up a meaning. Ask an open question such as “What deserves my attention?” Connect one detail in the card to your situation, then write down one realistic response. Study the Major Arcana story and each suit below, and use the Tarot Guide Book ($19.99 CAD) as a companion when ordering opens. Revisit your notes without forcing every event to fit a card.</p><a href="#learn">Explore the learning room →</a></details><details><summary>Does a difficult card mean I will have a bad day?</summary><p>No. An easy or hard label is a symbolic theme for reflection, not a reliable prediction. A demanding card can prompt you to slow down, seek help, or reconsider a pattern. Death speaks to endings and change; The Tower can question an unstable assumption. Neither establishes that harm is going to happen.</p></details></div></section>
<section class="wrap section-space learning-room" id="learn"><div class="tarot-topline"><p class="eyebrow">04 / Learn the language</p><span class="section-aside">The big story. The everyday details.</span></div><h2>There is a story<br><em>in every suit.</em></h2><a class="major-entry" href="major-arcana.html">{img('the-fool')}<div><p class="eyebrow">The Major Arcana story</p><h3>The Fool’s journey,<br>in three acts. →</h3><p>Build a self, meet the inner world, and return with a wider perspective. Explore all 22 cards through one thoughtful teaching framework.</p></div></a><div class="suit-links">{links}</div></section>'''
    return shell('Tarot — Daily draws & the stories in the cards','An animated daily tarot card, a three-card subscription preview at $5.99 CAD/month, and a learning room for the Major Arcana and all four suits.',body)

def major():
    acts=[]
    for act in LEARNING['acts']:
        cards=[c for c in CARDS if c['arcana']=='major' and act['range'][0]<=c['number']<=act['range'][1]]
        acts.append(f'''<section class="story-act" id="{act['id']}"><p class="eyebrow">{act['subtitle']}</p><h2>{act['title']}</h2><div class="story-prose">{''.join('<p>'+e(p)+'</p>' for p in act['paragraphs'])}</div><blockquote><p>{e(act['prompt'])}</p><cite>A question for this act</cite></blockquote><div class="study-grid">{''.join(card_tile(c) for c in cards)}</div></section>''')
    fool=CARDS[0]
    body=f'''<div class="wrap breadcrumb"><a href="index.html">Tarot</a><span>/</span><span>Major Arcana story</span></div><section class="wrap learning-hero"><div><p class="eyebrow">22 cards / A story you can revisit</p><h1>The Fool’s journey.<br><em>Three acts of becoming.</em></h1><p class="section-copy">The Major Arcana can be read as a story of meeting the world, exploring the inner life, and integrating what has been learned. You can enter that story anywhere.</p><nav class="chapter-links" aria-label="Jump to an act"><a href="#prologue">The Fool</a><a href="#act-one">Act I</a><a href="#act-two">Act II</a><a href="#act-three">Act III</a></nav></div><div class="learning-hero-art">{img('the-world',eager=True)}</div></section><section class="wrap prologue" id="prologue">{img('the-fool')}<div><p class="eyebrow">0 / The traveler</p><h2>Begin with <em>curiosity.</em></h2><p>The Fool is the prologue and the traveler, rather than a mistake to outgrow. Its openness makes a beginning possible; practical preparation helps keep that openness grounded. Ask what you can try without requiring certainty first.</p><p>Here, the next 21 cards form three groups of seven: I–VII, VIII–XIV, and XV–XXI. This is one editorial teaching structure, not a universal historical division. We use Strength VIII and Justice XI; some deck traditions reverse those positions.</p><p>Drawing a card does not diagnose a life stage or establish spiritual rank. The same themes return in new circumstances, and completing one journey can open another.</p></div></section><div class="wrap story-acts">{''.join(acts)}</div><section class="wrap learning-next"><p class="eyebrow">Bring it into daily life</p><h2>The big themes.<br><em>The everyday practice.</em></h2><p>The four suits explore thought, feeling, resources, and energy. Study a suit, or draw a card and give its theme one small, practical response.</p><a class="button button-gold" href="index.html#daily-draw">Draw your daily card →</a><div class="chapter-links">{''.join(f'<a href="{s["slug"]}.html">{s["name"]} →</a>' for s in LEARNING['suits'])}</div></section>'''
    return shell('Major Arcana — The Fool’s journey in three acts','Explore Act I, II, and III of a three-act Fool’s Journey, with all 22 Major Arcana cards, interpretation notes, and reflection questions.',body)

def suit_page(s):
    cards=[c for c in CARDS if c.get('suit')==s['slug']]
    body=f'''<div class="wrap breadcrumb"><a href="index.html">Tarot</a><span>/</span><span>{s['name']}</span></div><section class="wrap learning-hero"><div><p class="eyebrow">The Minor Arcana / {s['element']} / 14 cards</p><h1>{s['name']}.<br><em>{s['tagline']}</em></h1><p class="section-copy">{e(s['intro'])}</p><p class="domain-note">{e(s['domains'])}</p><a class="text-link" href="#cards">Meet all fourteen cards →</a></div><div class="learning-hero-art">{img(cards[0]['id'],eager=True)}</div></section><section class="wrap suit-explainer">{''.join(f'<article><p class="eyebrow">0{i+1} / Understanding {s["name"]}</p><h2>{e(title)}</h2><p>{e(text)}</p></article>' for i,(title,text) in enumerate(s['sections']))}</section><div class="wrap"><blockquote class="suit-question"><p>{e(s['prompt'])}</p><cite>A question to carry into your reading</cite></blockquote></div><section class="wrap section-space" id="cards"><p class="eyebrow">Ace to King / Upright meanings</p><h2>Meet the <em>{s['name']}.</em></h2><p class="section-copy">Fourteen perspectives, not fourteen predictions. Open a card for a practical focus and a reflection prompt. The court cards describe approaches anyone can use.</p><div class="study-grid">{''.join(card_tile(c) for c in cards)}</div></section><section class="wrap learning-next"><p class="eyebrow">Keep exploring</p><h2>A different suit.<br><em>A different angle.</em></h2><div class="chapter-links">{''.join(f'<a href="{other["slug"]}.html">{other["name"]} →</a>' for other in LEARNING['suits'] if other['slug']!=s['slug'])}<a href="major-arcana.html">The Major Arcana story →</a></div><a class="button button-gold" href="index.html#daily-draw">Draw your daily card →</a></section>'''
    return shell(f'{s["name"]} — What the suit represents',f'Learn the tarot suit of {s["name"]}: its {s["element"].lower()} symbolism, everyday themes, Ace-to-Ten story, court cards, and all fourteen upright meanings.',body)

def shop():
    prices={p['id']:p['price'] for p in CATALOG['products']}
    num_report=json.loads((ROOT/'data/numerology-topics.json').read_text())['report']
    savings=f"{Decimal(prices['book'])+Decimal(prices['deck'])-Decimal(prices['bundle']):.2f}"
    body=f'''<section class="wrap shop-hero"><p class="eyebrow">Books, cards &amp; a little wonder</p><h1>Make room<br>for your <em>ritual.</em></h1><p class="section-copy">A guide to learn with. A deck to grow with. Explore the Crystal Eye collection and find a starting point that feels like yours.</p><p class="coming-soon">Coming soon · ordering is not open yet</p></section>{merchandise('../',shop_page=True)}<section class="wrap ordering-info" id="ordering"><p class="eyebrow">Before you order</p><h2>A little more <em>to come.</em></h2><p>All listed prices are in Canadian dollars. The Tarot Guide Book is ${prices['book']} CAD, the Crystal Eye Tarot Deck is ${prices['deck']} CAD, and the Book + Card bundle is ${prices['bundle']} CAD—a saving of ${savings} compared with buying both separately.</p><p>Checkout has not been connected yet, and no orders or payments are being accepted. Product formats, fulfillment, shipping where applicable, and final checkout terms will be provided before ordering opens. Images show existing deck artwork, not finalized product packaging.</p><div class="shop-subscriptions"><article><h3>Full Numerology report</h3><p>A planned expanded reading for all 21 chart positions. ${num_report['price']} CAD, one-time purchase. Ordering is coming soon as the guide library is completed.</p><a class="text-link" href="../numerology/report.html">Explore the full report →</a></article><article><h3>The daily tarot ritual</h3><p>A planned three-card daily draw for yesterday, today, and tomorrow. $5.99 CAD/month, separate from merchandise and astrology.</p><a class="text-link" href="../tarot/index.html#three-card-preview">Try the animated preview →</a></article><article><h3>Your daily astrology email</h3><p>A planned daily reading for your Sun, Moon, and rising, with Sunday and monthly additions. $5.99 CAD/month.</p><a class="text-link" href="../astrology/index.html#email-preview">Preview your three signs →</a></article></div></section>'''
    return shell('Shop — Tarot guide, deck & bundle','Explore the Tarot Guide Book ($19.99 CAD), Crystal Eye Tarot Deck ($39.99 CAD), and Book + Card bundle ($49.99 CAD). Ordering coming soon.',body,True)

def main():
    OUT.mkdir(exist_ok=True)
    (OUT/'index.html').write_text(hub())
    (OUT/'major-arcana.html').write_text(major())
    for s in LEARNING['suits']:(OUT/f'{s["slug"]}.html').write_text(suit_page(s))
    (ROOT/'shop').mkdir(exist_ok=True);(ROOT/'shop/index.html').write_text(shop())
    payload=[{k:v for k,v in c.items() if k!='source'} for c in CARDS]
    (OUT/'card-data.mjs').write_text('// Generated by scripts/build_tarot.py; edit data/tarot-cards.json.\nexport default '+json.dumps(payload,ensure_ascii=False,indent=2)+';\n')
    print('Built tarot hub, five learning pages, shop, and shared 78-card data.')

if __name__=='__main__': main()
